-- Meteorology Science Academy lessons 10-14; idempotent draft seed.
with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'ديناميكا الغلاف الجوي والتحليل السينوبتيكي','التيار النفاث والتقارب والتباعد والحركة الرأسية وقراءة خرائط الطبقات العليا والسطح.',4,false from c on conflict(course_id,title) do update set description=excluded.description returning id,course_id),
ud as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'التيار النفاث والحركة الرأسية','التيار النفاث ومناطق التقارب والتباعد والحركة الرأسية للهواء.',1,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id),
um as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'التحليل السينوبتيكي للخرائط','قراءة خرائط 500 hPa والضغط السطحي وربط أنماط الطبقات المختلفة.',2,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id),
data as (select 'jet-stream-structure-and-weather','التيار النفاث: البنية والخصائص','تعرف إلى التيار النفاث وموقعه وبنيته والعوامل المؤثرة في سرعته ومساره.','{"blocks":[{"type":"heading","text":"ما هو التيار النفاث؟"},{"type":"text","text":"التيار النفاث (Jet Stream) نطاق ضيق نسبياً من رياح قوية في طبقات الجو العليا، غالباً قرب التروبوبوز. يتخذ مساراً متموجاً ويتغير موقعه وشدته مع الأنظمة الجوية والموسم."},{"type":"heading","text":"الأنواع الرئيسية"},{"type":"list","items":["التيار النفاث القطبي: يرتبط غالباً بمنطقة التباين الحراري القوي قرب الجبهة القطبية.","التيار النفاث شبه المداري: يوجد عادة في العروض شبه المدارية العليا ويرتبط بالدوران العام للغلاف الجوي.","قد تظهر فروع أو نوى نفاثة متعددة، ولا تكون جميعها متصلة أو ثابتة طوال الوقت."]},{"type":"heading","text":"لماذا تتكون الرياح القوية؟"},{"type":"text","text":"يسهم التباين الأفقي في الحرارة في تكوين قص رأسي للرياح وفق علاقة الرياح الحرارية. كما يؤثر تدرج الارتفاع الجهدي والدوران واسع النطاق في سرعة الرياح واتجاهها."},{"type":"heading","text":"النواة النفاثة"},{"type":"text","text":"النواة النفاثة هي منطقة السرعة القصوى ضمن التيار. يمكن تمثيلها على خرائط الرياح العلوية، ويجب الانتباه إلى مستوى الضغط المستخدم وإلى أن ارتفاع محور التيار يتغير مكانياً وزمانياً."},{"type":"heading","text":"علاقة التيار النفاث بالطقس"},{"type":"text","text":"تؤثر موجات التيار النفاث ومناطق التباعد والتقارب المرتبطة بها في تنظيم الصعود والهبوط وتطور المنخفضات. لكن وجود تيار نفاث فوق منطقة لا يعني تلقائياً حدوث هطول؛ فالرطوبة والاستقرار والبنية الرأسية عوامل أساسية."},{"type":"callout","text":"لا تفسر مناطق الدخول والخروج للتيار النفاث بقاعدة مبسطة واحدة دون مراعاة انحناء التيار والقص وموقع النواة وبنية الرياح ثلاثية الأبعاد."},{"type":"heading","text":"كيف نحلل التيار النفاث؟"},{"type":"list","items":["افحص سرعة الرياح واتجاهها عند 300 أو 250 hPa بحسب الحالة.","حدد محور التيار والنوى النفاثة وموجات الانحناء.","قارن خرائط الرياح مع الارتفاع الجهدي عند 500 hPa والضغط السطحي.","تابع انتقال النوى والموجات عبر خرائط متتابعة زمنياً."]},{"type":"example","title":"تطبيق تدريبي","text":"تظهر خريطة 300 hPa نواة رياح قوية قرب أخدود علوي. حدّد موقع النواة بالنسبة إلى الأخدود، ثم افحص مناطق التباعد العلوي والحركة الرأسية والرطوبة قبل تقدير أثرها على الطقس."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التيار النفاث عنصر مهم في الدوران العلوي وتطور الأنظمة الجوية. التحليل الصحيح يربط سرعته ومساره ببنية الموجات والتباعد والرصد السطحي."}]}',100,30,'["تعريف التيار النفاث وتمييز أنواعه الرئيسية","تحديد النواة النفاثة على خرائط الرياح العليا","ربط مسار التيار النفاث بتطور الأنظمة الجوية"]','التيار النفاث والحركة الرأسية'
union all
select 'upper-level-convergence-and-divergence','التقارب والتباعد في طبقات الجو','افهم تقارب الهواء وتباعده أفقياً وعلاقتهما بتغير الضغط والحركة الرأسية.','{"blocks":[{"type":"heading","text":"تعريف التقارب والتباعد"},{"type":"text","text":"التقارب الأفقي يعني أن الهواء يتجمع ضمن مساحة أفقية، بينما التباعد يعني انتشار الهواء وابتعاده أفقياً. يختلف أثرهما بحسب الطبقة الجوية وبحسب ما إذا كان التحليل عند السطح أو في المستويات العليا."},{"type":"heading","text":"التقارب والتباعد عند السطح"},{"type":"text","text":"قد يؤدي التقارب قرب السطح إلى دعم الصعود إذا لم توجد آلية تعويضية محلية أخرى. وقد يرتبط التباعد السطحي بهبوط نسبي أو بتغذية النظام بكتلة هوائية من محيطه، وفق الحالة."},{"type":"heading","text":"التقارب والتباعد في الطبقات العليا"},{"type":"text","text":"يمكن أن يدعم التباعد في الطبقات العليا صعود الهواء من أسفل للمحافظة على استمرارية الكتلة، بينما قد يرتبط التقارب العلوي بهبوط نسبي. يجب فحص البنية الرأسية كاملة بدلاً من تفسير طبقة واحدة بمعزل عن غيرها."},{"type":"formula","text":"D = ∂u/∂x + ∂v/∂y"},{"type":"text","text":"يمثل D التباعد الأفقي في الإحداثيات الديكارتية المحلية، وu وv مركبتي الرياح. تكون قيمة D موجبة للتباعد وسالبة للتقارب وفق هذا التعريف."},{"type":"heading","text":"الارتباط بالاستمرارية"},{"type":"text","text":"تربط معادلة الاستمرارية بين تغير الكثافة والتباعد الأفقي والحركة الرأسية. وفي تقريب الهواء غير القابل للانضغاط المستخدم تعليمياً، يؤدي التباعد الأفقي إلى تعويض رأسي مناسب، لكن الغلاف الجوي الحقيقي يتطلب مراعاة تغير الكثافة والضغط مع الارتفاع."},{"type":"heading","text":"كيف نحدد مناطق التباعد؟"},{"type":"list","items":["افحص خرائط التباعد المحسوب من الرياح أو المنتجات التشخيصية للنموذج.","قارن خرائط الرياح والارتفاع الجهدي عند أكثر من مستوى.","استخدم خرائط الحركة الرأسية والرطوبة لتقييم الاستجابة الجوية.","انتبه إلى أن التباعد قد يكون محلياً ومتغيراً زمنياً، وقد تختلف النتائج باختلاف دقة النموذج وطريقة الحساب."]},{"type":"callout","text":"التباعد العلوي وحده لا يكفي لتوقع الهطول؛ يجب أن تتوافر رطوبة ورفع مناسب واستقرار ملائم، وأن يكون التوزيع الرأسي متسقاً."},{"type":"example","title":"مثال تحليلي","text":"تظهر منطقة تباعد علوي فوق منطقة رطبة مع تقارب سطحي. هذه مجموعة إشارات داعمة لصعود الهواء، لكن ينبغي التحقق من الحركة الرأسية وملف الاستقرار وتطورها زمنياً."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التقارب والتباعد يصفان تنظيم تدفق الهواء أفقياً. قيمتهما التنبؤية تظهر عند دمجهما مع الاستمرارية والحركة الرأسية والرطوبة."}]}',110,30,'["تعريف التقارب والتباعد وتمييز إشارة التباعد","شرح العلاقة المفاهيمية بمعادلة الاستمرارية","تفسير التقارب والتباعد مع الحركة الرأسية والرطوبة"]','التيار النفاث والحركة الرأسية'
union all
select 'vertical-motion-and-omega','الحركة الرأسية للهواء ومؤشر أوميغا','تعرف إلى الصعود والهبوط ومفهوم أوميغا وكيفية تفسير خرائط الحركة الرأسية.','{"blocks":[{"type":"heading","text":"الحركة الرأسية في الغلاف الجوي"},{"type":"text","text":"الحركة الرأسية هي مركبة حركة الهواء إلى أعلى أو أسفل. تؤثر في التبريد والاحترار الأديباتي وتكوّن السحب والهطول، وترتبط بالتقارب والتباعد والتضاريس والجبهات والحمل."},{"type":"heading","text":"السرعة الرأسية الهندسية"},{"type":"text","text":"يرمز w عادة إلى السرعة الرأسية في الإحداثيات الهندسية، ويكون موجباً إلى أعلى في اصطلاح شائع. وحدته متر في الثانية."},{"type":"heading","text":"إحداثيات الضغط ومؤشر أوميغا"},{"type":"text","text":"في كثير من نماذج الطقس تستخدم إحداثيات الضغط، ويعرف أوميغا بأنه معدل تغير الضغط مع الزمن للطرد المتحرك رأسياً. وفق الاصطلاح المعتاد تكون أوميغا السالبة دلالة على الصعود، والموجبة دلالة على الهبوط."},{"type":"formula","text":"ω = Dp/Dt"},{"type":"text","text":"وحدة أوميغا المعتادة Pa/s أو hPa/h بحسب المنتج. لا تخلط بين إشارة أوميغا وإشارة w؛ فهما معرفان في نظامي إحداثيات مختلفين."},{"type":"heading","text":"أثر الصعود والهبوط"},{"type":"list","items":["الصعود: يتمدد الهواء غالباً ويبرد أديباتياً، وقد تزداد الرطوبة النسبية حتى التشبع إذا كانت الرطوبة كافية.","الهبوط: ينضغط الهواء غالباً ويسخن أديباتياً، ما قد يقلل الرطوبة النسبية ويحد من تكوّن السحب.","شدة الحركة وعمقها واستمرارها مهمة بقدر أهمية اتجاهها."]},{"type":"heading","text":"قراءة خرائط أوميغا"},{"type":"text","text":"افحص المستوى الرأسي الذي تعرضه الخريطة، ووحدة القياس، وتعريف الإشارة في مصدر البيانات. قارن خرائط 700 و500 و850 hPa عند الحاجة، ولا تستنتج صعوداً عميقاً من إشارة عند مستوى واحد فقط."},{"type":"callout","text":"أوميغا ليست قياساً مباشراً للهطول. يمكن أن يحدث صعود دون هطول إذا كان الهواء جافاً، كما قد تختلف الاستجابة السحابية باختلاف الاستقرار والميكروفيزياء."},{"type":"example","title":"مثال قراءة","text":"تظهر خريطة 700 hPa قيماً سالبة لأوميغا فوق منطقة رطبة. تشير القيم وفق الاصطلاح المعتاد إلى صعود عند ذلك المستوى؛ تحقق من امتداد الصعود رأسياً ومن الرطوبة والاستقرار والرصد."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"أوميغا تصف الحركة الرأسية في إحداثيات الضغط. تفسيرها يتطلب فهم الإشارة والوحدة والمستوى ودمجها مع الرطوبة وبقية عناصر التحليل."}]}',120,30,'["التمييز بين السرعة الرأسية الهندسية وأوميغا","تفسير إشارة أوميغا ووحداتها","قراءة خرائط الحركة الرأسية وربطها بالرطوبة والاستقرار"]','التيار النفاث والحركة الرأسية'
union all
select 'synoptic-analysis-500hpa-maps','تحليل خرائط 500 hPa','تعلم قراءة الارتفاع الجهدي والأخاديد والنتوءات والحرارة والدوامية عند 500 hPa.','{"blocks":[{"type":"heading","text":"لماذا مستوى 500 hPa؟"},{"type":"text","text":"يقع مستوى 500 hPa في الطبقات الوسطى من التروبوسفير في معظم الحالات، ويستخدم كثيراً لتتبع الموجات واسعة النطاق والأخاديد والنتوءات والدوامية. يتغير ارتفاع هذا المستوى حسب الحالة الجوية."},{"type":"heading","text":"العناصر الأساسية على الخريطة"},{"type":"list","items":["خطوط الارتفاع الجهدي: تبين شكل الموجات ومواقع الأخاديد والنتوءات.","درجة الحرارة: تساعد على وصف الكتل الهوائية والتدرج الحراري في المستوى.","الدوامية: تساعد على تتبع الدوران والاضطرابات العلوية.","الرياح: تبين اتجاه التدفق وسرعته وتطور النمط."]},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["حدد مراكز الارتفاعات والأخاديد والنتوءات.","تتبع محور الأخدود واتجاه حركة الموجة بين الخرائط الزمنية.","حدد مناطق الدوامية النسبية ومناطق انتقالها أو ازديادها.","قارن مع خرائط 300 hPa للتيار النفاث والتباعد العلوي.","اربط النمط بخريطة الضغط السطحي والرطوبة والحركة الرأسية."]},{"type":"heading","text":"الدوامية والتطور الجوي"},{"type":"text","text":"قد تكون مناطق انتقال الدوامية أو تغيرها ذات أهمية في تشخيص الدعم الديناميكي للصعود. لكن لا توجد قاعدة منفردة تجعل كل قيمة دوامية مرتفعة دليلاً على هطول؛ فالموقع والحركة والتباعد والرطوبة عوامل حاسمة."},{"type":"heading","text":"التحليل الزمني"},{"type":"text","text":"الخريطة المفردة تصف حالة عند وقت معين، أما التنبؤ فيحتاج إلى مقارنة التحليلات والتوقعات المتتابعة لتحديد سرعة حركة الأخدود وتغير شدته وتفاعل الموجات القصيرة مع النمط العام."},{"type":"callout","text":"لا تخلط بين خطوط الارتفاع الجهدي عند 500 hPa وخطوط الضغط السطحي؛ لكل خريطة متغير ومستوى مرجعي مختلف."},{"type":"example","title":"تطبيق تدريبي","text":"تظهر خريطة 500 hPa أخدوداً يقترب من شرق المتوسط مع موجة قصيرة أمام محوره. تتبع الموجة والدوامية، ثم افحص التيار النفاث والتباعد العلوي والضغط السطحي والرطوبة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"خريطة 500 hPa أداة محورية لفهم النمط السينوبتيكي. تزداد فائدتها عند ربطها بالطبقات العليا والسطحية والتغير الزمني."}]}',130,35,'["تحديد الأخاديد والنتوءات على خرائط 500 hPa","قراءة الارتفاع الجهدي والدوامية والحرارة","بناء تحليل زمني وربط المستوى المتوسط بالسطح"]','التحليل السينوبتيكي للخرائط'
union all
select 'surface-pressure-and-upper-air-synthesis','تحليل الضغط السطحي وربطه بالطبقات العليا','حلل مراكز الضغط والجبهات وتدرج الضغط واربطها بالبنية الجوية العليا.','{"blocks":[{"type":"heading","text":"خريطة الضغط السطحي"},{"type":"text","text":"تعرض خريطة الضغط عند مستوى سطح البحر توزيع الضغط بعد اختزاله إلى مستوى مرجعي موحد. تساعد على تحديد المنخفضات والمرتفعات والجبهات وتدرج الضغط، مع مراعاة التضاريس وجودة الرصد."},{"type":"heading","text":"مراكز الضغط وتدرجه"},{"type":"text","text":"تحدد خطوط تساوي الضغط (Isobars) مواقع القيم المتساوية. تقارب الخطوط يدل غالباً على تدرج ضغط أفقي أقوى، ويرتبط عادة برياح أقوى إذا بقيت العوامل الأخرى متقاربة، مع تعديل الاحتكاك والتضاريس والدوران."},{"type":"heading","text":"قراءة المنخفضات والمرتفعات"},{"type":"list","items":["المنخفض: مركز ضغط أقل من محيطه، ويرتبط في نصف الكرة الشمالي بدوران إعصاري قرب السطح في الظروف المعتادة.","المرتفع: مركز ضغط أعلى من محيطه، ويرتبط في نصف الكرة الشمالي بدوران مضاد للإعصار قرب السطح في الظروف المعتادة.","الجبهات: مناطق انتقال بين كتل هوائية مختلفة، وتحدد من اجتماع الحرارة والرياح والرطوبة والتغيرات السطحية لا من الضغط وحده."]},{"type":"heading","text":"لماذا نربط السطح بالطبقات العليا؟"},{"type":"text","text":"قد يتأثر تطور المنخفض السطحي بأخدود علوي أو موجة قصيرة أو تباعد في الطبقات العليا. ويساعد الربط بين الضغط السطحي و500 hPa و300 hPa على فهم الدعم الديناميكي وتطور النظام واتجاه حركته."},{"type":"heading","text":"قائمة فحص للتحليل المتكامل"},{"type":"list","items":["حدد مراكز الضغط والجبهات وتدرج الضغط على خريطة السطح.","افحص الحرارة والرطوبة والرياح السطحية ومحطات الرصد.","حلل الأخاديد والنتوءات والدوامية عند 500 hPa.","حدد محور التيار النفاث ومناطق التباعد عند 300 أو 250 hPa.","قارن الحركة الرأسية والرطوبة في المستويات المناسبة.","تابع تسلسل الخرائط زمنياً وقارن التحليل بالرصد الفعلي."]},{"type":"callout","text":"لا تستنتج شدة الحالة أو كمية الهطول من عمق المنخفض أو تقارب خطوط الضغط وحدهما. يلزم تحليل الرطوبة والاستقرار والديناميكا والبنية الرأسية."},{"type":"example","title":"حالة تحليلية افتراضية","text":"يوجد منخفض سطحي مع جبهة باردة، ويقترب أخدود علوي. حلل توافق توقيت الأخدود مع المنخفض وموقع التباعد العلوي وتوزيع الرطوبة والحركة الرأسية والقص، ثم قارن التوقعات بالرصد."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التحليل السينوبتيكي المتكامل يجمع خريطة الضغط السطحي مع خرائط الطبقات العليا والرصد. لا توجد خريطة واحدة تكفي وحدها لتفسير الحالة الجوية."}]}',140,40,'["قراءة خطوط تساوي الضغط ومراكز المنخفضات والمرتفعات","تحليل الجبهات بالاستعانة بعناصر الرصد","دمج خرائط السطح و500 hPa و300 hPa في تحليل واحد"]','التحليل السينوبتيكي للخرائط'),
lesson_data as (select slug,title,summary,(content)::jsonb content,ord,mins,(objectives)::jsonb objectives,unit from data)
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case when d.unit='التيار النفاث والحركة الرأسية' then ud.id else um.id end,d.slug,d.title,d.summary,d.content,false,d.ord,'intermediate',d.mins,d.objectives,ch.title,d.unit
from lesson_data d cross join c cross join ch cross join ud cross join um
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;